configuration:
{
  "name": "jobpulse-metrics",
  "networks": {
    "default": {
      "name": "jobpulse-metrics_default",
      "ipam": {}
    }
  },
  "services": {
    "app": {
      "build": {
        "context": "/Users/huylegia/Coding-Projects/jobpulse",
        "dockerfile": "Dockerfile"
      },
      "cpus": 2,
      "command": null,
      "depends_on": {
        "kafka": {
          "condition": "service_healthy",
          "required": true
        },
        "postgres": {
          "condition": "service_healthy",
          "required": true
        },
        "rabbitmq": {
          "condition": "service_healthy",
          "required": true
        }
      },
      "entrypoint": null,
      "environment": {
        "DATABASE_PASSWORD": "metrics-local-only",
        "DATABASE_URL": "jdbc:postgresql://postgres:5432/jobpulse_metrics",
        "DATABASE_USER": "jobpulse",
        "GREENHOUSE_BASE_URL": "http://host.docker.internal:18090",
        "JOBPULSE_DISCOVERY_INITIAL_DELAY_MS": "86400000",
        "JOBPULSE_INGESTION_INITIAL_DELAY_MS": "86400000",
        "KAFKA_BOOTSTRAP_SERVERS": "kafka:29092",
        "LOGGING_LEVEL_COM_HUY_JOBPULSE": "WARN",
        "MANAGEMENT_TRACING_SAMPLING_PROBABILITY": "0",
        "RABBITMQ_HOST": "rabbitmq",
        "RABBITMQ_PASSWORD": "metrics-local-only",
        "RABBITMQ_USER": "jobpulse",
        "SPRING_RABBITMQ_LISTENER_SIMPLE_CONCURRENCY": "1",
        "SPRING_RABBITMQ_LISTENER_SIMPLE_MAX_CONCURRENCY": "1"
      },
      "image": "jobpulse-metrics-app:local",
      "mem_limit": "2147483648",
      "networks": {
        "default": null
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 8080,
          "published": "18082",
          "protocol": "tcp"
        }
      ]
    },
    "kafka": {
      "cpus": 2,
      "command": null,
      "entrypoint": null,
      "environment": {
        "KAFKA_ADVERTISED_LISTENERS": "PLAINTEXT://kafka:29092",
        "KAFKA_AUTO_CREATE_TOPICS_ENABLE": "false",
        "KAFKA_CONTROLLER_LISTENER_NAMES": "CONTROLLER",
        "KAFKA_CONTROLLER_QUORUM_VOTERS": "1@kafka:29093",
        "KAFKA_INTER_BROKER_LISTENER_NAME": "PLAINTEXT",
        "KAFKA_LISTENERS": "CONTROLLER://:29093,PLAINTEXT://:29092",
        "KAFKA_LISTENER_SECURITY_PROTOCOL_MAP": "CONTROLLER:PLAINTEXT,PLAINTEXT:PLAINTEXT",
        "KAFKA_NODE_ID": "1",
        "KAFKA_OFFSETS_TOPIC_REPLICATION_FACTOR": "1",
        "KAFKA_PROCESS_ROLES": "broker,controller",
        "KAFKA_TRANSACTION_STATE_LOG_MIN_ISR": "1",
        "KAFKA_TRANSACTION_STATE_LOG_REPLICATION_FACTOR": "1"
      },
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "/opt/kafka/bin/kafka-topics.sh --bootstrap-server localhost:29092 --list \u003e/dev/null 2\u003e\u00261"
        ],
        "timeout": "5s",
        "interval": "3s",
        "retries": 40
      },
      "image": "apache/kafka:4.1.0",
      "mem_limit": "1073741824",
      "networks": {
        "default": null
      }
    },
    "postgres": {
      "cpus": 2,
      "command": null,
      "entrypoint": null,
      "environment": {
        "POSTGRES_DB": "jobpulse_metrics",
        "POSTGRES_PASSWORD": "metrics-local-only",
        "POSTGRES_USER": "jobpulse"
      },
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "pg_isready -U jobpulse -d jobpulse_metrics"
        ],
        "timeout": "3s",
        "interval": "2s",
        "retries": 40
      },
      "image": "postgres:17-alpine",
      "mem_limit": "1073741824",
      "networks": {
        "default": null
      },
      "volumes": [
        {
          "type": "volume",
          "source": "metrics-postgres",
          "target": "/var/lib/postgresql/data",
          "volume": {}
        }
      ]
    },
    "rabbitmq": {
      "cpus": 1,
      "command": null,
      "entrypoint": null,
      "environment": {
        "RABBITMQ_DEFAULT_PASS": "metrics-local-only",
        "RABBITMQ_DEFAULT_USER": "jobpulse"
      },
      "healthcheck": {
        "test": [
          "CMD",
          "rabbitmq-diagnostics",
          "-q",
          "ping"
        ],
        "timeout": "5s",
        "interval": "3s",
        "retries": 40
      },
      "image": "rabbitmq:4-management-alpine",
      "mem_limit": "536870912",
      "networks": {
        "default": null
      }
    }
  },
  "volumes": {
    "metrics-postgres": {
      "name": "jobpulse-metrics_metrics-postgres"
    }
  }
}
